def transform(grid):
    H,W=len(grid),len(grid[0])
    pts=[(r,c) for r in range(H) for c in range(W) if grid[r][c]==1]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts)
    mask={(r-r0,c-c0) for r,c in pts}
    # Key is the repeated non-1 colored rectangle, horizontally ordered.
    non={(r,c) for r in range(H) for c in range(W) if grid[r][c] not in (0,1)}
    comps=[]
    while non:
        seed=non.pop(); comp={seed}; todo=[seed]
        while todo:
            r,c=todo.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    q=(r+dr,c+dc)
                    if q in non: non.remove(q);comp.add(q);todo.append(q)
        comps.append(comp)
    comp=max(comps,key=len)
    sr=min(r for r,c in comp); er=max(r for r,c in comp)
    sc=min(c for r,c in comp); ec=max(c for r,c in comp)
    # use the palette row, restoring the omitted 1-colored middle cell
    colors=[grid[sr][c] for c in range(sc,ec+1)]
    # Infer the gap cell color 1 from the sequence layout of the palette.
    if len(colors)==4 and 1 not in colors:
        colors.insert(2,1)
    anchor=colors.index(1)
    out=[[0]*W for _ in range(H)]
    h=r1-r0+1
    for i,col in enumerate(colors):
        top=r0+(i-anchor)*h
        for dr,dc in mask:
            rr,cc=top+dr,c0+dc
            if 0<=rr<H and 0<=cc<W: out[rr][cc]=col
    return out
